import { FrameworkElement, IFrameworkElementProps, IFrameworkElementState } from '../FrameworkElement';
import * as React from 'react';
import { Binding } from '@antimatterjs/react';
import { IItemsControlProps, IItemsControlState, ItemsControl } from '@antimatterjs/positron/src/Controls/ItemsControl';
import { ScrollBarVisibility } from '@antimatterjs/positron/src/Enums';

export interface IPanelProps extends IFrameworkElementProps
{
    Background?: string|Binding,
    BorderBrush?: string|Binding,
    BorderThickness?: string | Binding,
    Padding?: string,
    BoxShadow?: string,
    ItemsParent?: ItemsControl<IItemsControlProps, IItemsControlState>,
    HorizontalScrollBarVisibility?: ScrollBarVisibility,
    VerticalScrollBarVisibility?: ScrollBarVisibility
}

export interface IPanelState extends IFrameworkElementState
{
    Background?: string,
    BorderBrush?: string,
    BorderThickness?: string 
}

export abstract class Panel<P extends IPanelProps = {}, S extends IPanelState = {}> extends FrameworkElement<P,S>
{
    protected /* override */ getCSSStyles() : React.CSSProperties
    {
        var styles = {
            background: this.state.Background,
            borderColor: this.state.BorderBrush,
            borderWidth: this.state.BorderThickness,
            borderStyle: "solid",
            boxShadow: this.props.BoxShadow,
            padding: this.props.Padding,
            overflowX: Panel.GetScrollBarVisibilityCSSValue(this.props.HorizontalScrollBarVisibility),
            overflowY: Panel.GetScrollBarVisibilityCSSValue(this.props.VerticalScrollBarVisibility)            
        };
        return Object.assign(super.getCSSStyles(), styles);
    }

    protected /* override */ constructClasses() : string
    {
        return "amx-ptn-panel " + super.constructClasses();
    }

    protected /* override */ renderElement(): JSX.Element
    {
        return (<>{this.props.children}</>);
    }

    private static GetScrollBarVisibilityCSSValue(v?: ScrollBarVisibility): "auto" | "hidden" | "scroll" 
    {
        switch (v)
        {            
            case undefined:
            case ScrollBarVisibility.Hidden:
                return "hidden";
            case ScrollBarVisibility.Visible:
                return "scroll";
            case ScrollBarVisibility.Auto:
            default:
                return "auto";
        }
    }
}

